  4527	                ((p >= 0x10000000u && p < 0x20000000u) ? "PSRAM-CBUS" : "其它")));
  4528	    } else {
  4529	        syslog(LOG_WARNING, "[vperf] ui buf: 取不到\n");
  4530	    }
  4531	}
