  4547	    syslog(LOG_WARNING,
  4548	           "[vperf] ui 5s renders=%u slow=%u render=%ums flush=%ums | "
  4549	           "fill_sq=%u fill_round=%u label=%u img=%u other=%u\n",
  4550	           (unsigned)s_probe.renders, (unsigned)s_probe.slow,
  4551	           (unsigned)s_probe.render_ms, (unsigned)s_probe.flush_ms,
  4552	           (unsigned)s_probe.fill_sq, (unsigned)s_probe.fill_round,
  4553	           (unsigned)s_probe.label, (unsigned)s_probe.img,
  4554	           (unsigned)s_probe.other);
  4555	
  4556	    s_probe.renders = 0;
  4557	    s_probe.slow = 0;
  4558	    s_probe.render_ms = 0;
  4559	    s_probe.flush_ms = 0;
  4560	    s_probe.fill_sq = 0;
  4561	    s_probe.fill_round = 0;
  4562	    s_probe.label = 0;
  4563	    s_probe.img = 0;
  4564	    s_probe.other = 0;
  4565	}
