  9652	static void helm_shell_rebuild_once(void)
  9653	{
  9654	    map_page_t * map = s_sh.map;
  9655	    lv_obj_t * root;
  9656	    uint32_t i;
  9657	
  9658	    if (map == NULL || !s_sh.attached) {
  9659	        return;
  9660	    }
  9661	
  9662	    root = map_page_root(map);
  9663	    if (root == NULL) {
  9664	        return;
  9665	    }
  9666	
  9667	    /* 换主题才走这里 ⇒ 打点不心疼：真卡住时"最后一行"就是现场（这一族踩过两次）。 */
  9668	    syslog(LOG_WARNING, "[theme] delete begin n=%u",
  9669	           (unsigned)lv_obj_get_child_count(root));
  9670	
  9671	    for (i = lv_obj_get_child_count(root); i > 0u; i--) {
  9672	        lv_obj_t * c = lv_obj_get_child(root, i - 1u);
  9673	
  9674	        if (c != NULL && lv_obj_has_flag(c, LV_OBJ_FLAG_USER_2)) {
  9675	            lv_obj_delete(c);
  9676	        }
  9677	    }
