  9681	    s_sh.attached = false;
  9682	    helm_shell_attach(map);        /* 按开机顺序重建 */
  9683	    syslog(LOG_WARNING, "[theme] attach done");
  9684	    helm_apply_view();             /* 恢复当前页 */
  9685	    syslog(LOG_WARNING, "[theme] view done");
  9686	
  9687	    /*
  9688	     * 重建把上一轮入场动画的对象一起删了（`lv_obj_delete` 会清掉挂在对象上的
  9689	     * 动画），新控件默认全不透明：
  9690	     *   · 之前"还没亮过"（pending 期间保持透明，或动画还没走完就被删）⇒ 补播一次；
  9691	     *   · 之前"已经亮过"（正常播完，或兜底定时器已落末态）⇒ 不补播，新控件直接
  9692	     *     可见。否则会把已经显示的内容再淡入一遍（"出现→消失→再出现"）。
  9693	     */
  9694	    if (!s_sb_in_visible) {
  9695	        helm_shell_enter_anim();
  9696	    }
  9697	}
